			long upper = fixture.term(uppercase), lower = fixture.term(lowercase);
			long a = fixture.term(values.createLiteral("a")), b = fixture.term(values.createLiteral("b"));
			ValuesRow[] input = {
					new ValuesRow(new int[] { KEY, PAYLOAD }, new long[] { upper, a }),
					new ValuesRow(new int[] { PAYLOAD }, new long[] { b }),
					new ValuesRow(new int[] { KEY, PAYLOAD }, new long[] { lower, a }) };
			try (OptionalCompatibilityIndex index = build(fixture, input, new int[] { KEY, PAYLOAD },
					new int[] { KEY })) {
				assertThat(index.spilled()).isFalse();
				fixture.row.bind(KEY, lower);
				List<String> payloads = new ArrayList<>();
				try (OptionalCompatibilityIndex.Probe probe = index.probe(fixture.row)) {
					while (probe.next()) {
						payloads.add(probe.current().cell(1).value().stringValue());
					}
				}
				assertThat(payloads).containsExactly("a", "b", "a");
			}
